const express = require('express');
const { Scalekit } = require('@scalekit-sdk/node');

const app = express();
const port = 3001;

// Initialize Scalekit client
const scalekit = new Scalekit(
  process.env.SCALEKIT_ENVIRONMENT_URL || 'https://example.scalekit.com',
  process.env.SCALEKIT_CLIENT_ID || 'client_id',
  process.env.SCALEKIT_CLIENT_SECRET || 'client_secret'
);

// Authentication middleware
const authMiddleware = async (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const token = authHeader.split(' ')[1];

  try {
    // Validate the token and check for required scopes
    const isValid = await scalekit.validateToken(token, { requiredScopes: ['todo:read'] });

    if (isValid) {
      next();
    } else {
      res.status(403).json({ error: 'Insufficient scope or invalid token' });
    }
  } catch (error) {
    console.error('Token validation error:', error);
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Protected /todos endpoint
app.get('/todos', authMiddleware, (req, res) => {
  res.json([
    { id: 1, title: 'Learn Scalekit' },
    { id: 2, title: 'Build Middleware' }
  ]);
});

app.listen(port, () => {
  console.log(`Server listening on port ${port}`);
});

